import os

code = r"""
#include <stdio.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>
#include <stdbool.h>

#define NUM_THREADS 16
#define ITEMS_PER_THREAD 200000

typedef struct node {
    int value;
    struct node *next;
} node_t;

typedef struct stack {
    _Atomic(node_t*) head;
} stack_t;

_Atomic(node_t*) hazard_pointers[NUM_THREADS];

_Thread_local node_t* retired_list[NUM_THREADS * 2];
_Thread_local int retired_count = 0;

void retire_node(node_t *node) {
    retired_list[retired_count++] = node;
    if (retired_count == NUM_THREADS * 2) {
        node_t* hp[NUM_THREADS];
        for (int i = 0; i < NUM_THREADS; i++) {
            hp[i] = atomic_load_explicit(&hazard_pointers[i], memory_order_acquire);
        }

        int new_count = 0;
        for (int i = 0; i < retired_count; i++) {
            node_t *r = retired_list[i];
            bool guarded = false;
            for (int j = 0; j < NUM_THREADS; j++) {
                if (hp[j] == r) {
                    guarded = true;
                    break;
                }
            }
            if (guarded) {
                retired_list[new_count++] = r;
            } else {
                free(r);
            }
        }
        retired_count = new_count;
    }
}

void push(stack_t *s, int value) {
    node_t *new_node = malloc(sizeof(node_t));
    new_node->value = value;
    node_t *old_head = atomic_load_explicit(&s->head, memory_order_relaxed);
    do {
        new_node->next = old_head;
    } while (!atomic_compare_exchange_weak_explicit(&s->head, &old_head, new_node,
        memory_order_release, memory_order_relaxed));
}

bool pop(stack_t *s, int *value, int thread_id) {
    node_t *old_head;
    while (true) {
        old_head = atomic_load_explicit(&s->head, memory_order_seq_cst);
        if (old_head == NULL) {
            return false;
        }
        atomic_store_explicit(&hazard_pointers[thread_id], old_head, memory_order_seq_cst);

        if (atomic_load_explicit(&s->head, memory_order_seq_cst) != old_head) {
            continue;
        }

        node_t *next_node = old_head->next;
        if (atomic_compare_exchange_weak_explicit(&s->head, &old_head, next_node,
            memory_order_release, memory_order_relaxed)) {
            break;
        }
    }

    *value = old_head->value;
    atomic_store_explicit(&hazard_pointers[thread_id], NULL, memory_order_seq_cst);

    retire_node(old_head);
    return true;
}

stack_t global_stack;

void* thread_func(void* arg) {
    int thread_id = (int)(long)arg;
    for (int i = 0; i < ITEMS_PER_THREAD; i++) {
        push(&global_stack, i);
        int val;
        while (!pop(&global_stack, &val, thread_id));
    }
    return NULL;
}

int main() {
    atomic_init(&global_stack.head, NULL);
    for(int i = 0; i < NUM_THREADS; i++) {
        atomic_init(&hazard_pointers[i], NULL);
    }

    pthread_t threads[NUM_THREADS];
    for (long i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_func, (void*)i);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("FLAG: Hazard Stack Success!\n");
    return 0;
}
"""

with open("target.c", "w") as f:
    f.write(code.lstrip())
